from pathlib import Path

def replace_paragraph(path, prefix, text):
 p=Path(path); lines=p.read_text().splitlines(); matches=[i for i,l in enumerate(lines) if l.startswith(prefix)]
 if len(matches)!=1: raise ValueError((path,prefix,matches))
 lines[matches[0]]=text
 p.write_text('\n'.join(lines)+'\n')

def insert_before(path, heading, text):
 p=Path(path);s=p.read_text();assert heading in s,path;p.write_text(s.replace(heading,text+'\n\n'+heading,1))

for suffix,paragraph in [('', "When a task turn ends with `max-tokens`, the client continues the exact running attempt up to `maxTaskOutputContinuations`. Continuation messages retain `team-task-assignment` provenance and deterministic per-turn message ids. Their Session inbox records count against the attempt budget across delivery reloads; duplicate turn notifications do not consume another continuation. The input is flushed behind the pre-step barrier before the model can consume it. A normal end without a report receives up to `maxTaskReportReminders` reminders, then fails with `TEAM_TASK_REPORT_MISSING`; zero disables this missing-report recovery. Exhausted model-request errors settle the exact still-running attempt with their original code and message. Cancelled, expired, settled, or replaced attempts are never revived."),('.zh', '任务 turn 以 `max-tokens` 结束时，client 最多按 `maxTaskOutputContinuations` 接续同一 running attempt。续跑消息保留 `team-task-assignment` 来源和按 turn 派生的确定性消息 ID。Session inbox 记录用于累计 attempt 预算，delivery 重载后仍有效；重复 turn 通知不额外消耗次数。输入经 pre-step 屏障 flush 后模型才可消费。正常结束但未 report 时，最多提醒 `maxTaskReportReminders` 次，之后以 `TEAM_TASK_REPORT_MISSING` 失败；零表示关闭未报告恢复。模型请求重试耗尽后，以原始 code 和 message 结算仍在运行的准确 attempt。已取消、过期、结算或替换的 attempt 不会被重新唤醒。')]:
 prefix='When a task Agent' if not suffix else '当 task Agent'
 replace_paragraph(f'packages/team/team-agent-client/README{suffix}.md',prefix,paragraph)
 insert_before(f'packages/team/team-agent-client/README{suffix}.md','## Configuration' if not suffix else '## 配置',
  'A new assignment includes the latest settled attempt outcome and matching review decision, so a replacement worker can use prior evidence without inheriting another worker’s conversation. `maxTaskHandoffBytes` bounds this UTF-8 handoff, including its explicit truncation notice, and defaults to `16384` (minimum `128`). `maxTaskReportReminders` defaults to `1`. Task descriptions and the current assignment provenance remain separate from the bounded handoff.' if not suffix else '新 assignment 携带最近已结算 attempt 的结果及对应审阅决定，使接手 worker 无需继承另一 worker 的对话即可获取已有证据。`maxTaskHandoffBytes` 限制这段 UTF-8 交接内容（包含明确截断提示），默认 `16384`，最小 `128`。`maxTaskReportReminders` 默认为 `1`。原任务说明及当前 assignment 来源独立于这段有界交接内容。')
 p=Path(f'packages/team/team-agent-client/README{suffix}.md');s=p.read_text();old='A failed connection or rejected Link `done` reconnects after `reconnectDelayMs` only while the exact binding remains current.' if not suffix else 'connection failure 或被 reject 的 Link `done`只会在准确 binding 仍为 current 时，于 `reconnectDelayMs`后 reconnect。';new='Recoverable connection or Link `done` failures reconnect after `reconnectDelayMs` only while the exact binding remains current. A provider-classified `TeamLinkConnectionError` with `retryable: false` pauses reconnect until provider registration changes or a new activation is bound.' if not suffix else '可恢复的 connection 或 Link `done` 故障只会在准确 binding 仍为 current 时，于 `reconnectDelayMs` 后重连。Provider 标记为 `retryable: false` 的 `TeamLinkConnectionError` 会暂停重连，直到 provider 重新注册或绑定新的 activation。';assert old in s;p.write_text(s.replace(old,new))

for suffix in ['', '.zh']:
 path=f'packages/team/tool-team-task/README{suffix}.md'
 replace_paragraph(path,'`team_task_wait(task_id)`',
 '`team_task_wait(task_id)` waits for a task admitted through the same coordinator capability, including configured review. Completed results retain `summary`, `evidence`, `artifacts`, `changed_paths`, `verification`, and `integration` when present. Failed results always name `outcome` as `failed`, `released`, or `lease-expired`, with the original failure code/message when available. The existing tool spill policy owns oversized rendered output and retains its readable full-value locator. Cancelling this call stops only the wait. Worker transcripts and lease internals are not included.' if not suffix else '`team_task_wait(task_id)` 等待通过同一 coordinator capability 准入的任务，包括配置的审阅。完成结果保留已有的 `summary`、`evidence`、`artifacts`、`changed_paths`、`verification` 和 `integration`。失败结果始终以 `outcome` 区分 `failed`、`released` 和 `lease-expired`，并保留已有 failure code/message。超大渲染结果由现有 tool spill policy 处理，保留可读取的完整结果定位信息。取消调用只停止等待；结果不包含 worker 对话和 lease 内部状态。')
 p=Path(path);s=p.read_text();lines=s.splitlines()
 for i,line in enumerate(lines):
  if line.startswith('`team_worker_pool_set('):
   lines[i]='`team_worker_pool_set(worker_count)` resizes the worker pool within the deployment limit and returns requested, target, active, idle, busy, queued, and saturation counts. Busy workers finish their work; ready tasks may queue. The coordinator prompt owns delegation policy.' if not suffix else '`team_worker_pool_set(worker_count)` 在部署上限内调整 worker pool，返回 requested、target、active、idle、busy、queued 和 saturation 状态。忙碌 worker 完成已有工作，ready task 可以排队。委派策略由 coordinator prompt 统一说明。'
  if line.startswith('`team_task_start('):
   lines[i]='`team_task_start(subject, instructions, read_scopes?, write_scopes?)` admits a bounded worker task with a self-contained brief, deliverable, and validation. Use narrow non-overlapping paths for concurrent writers; tasks without filesystem work leave scopes empty. Absolute paths inside the coordinator workspace become relative paths; outside paths reject. The result returns `task_id`, `phase`, and review facts. Delegation should save time or context and produce independently verifiable work.' if not suffix else '`team_task_start(subject, instructions, read_scopes?, write_scopes?)` 准入一个有界 worker task，brief 明确交付物和验收。并行 writer 使用窄且不重叠的路径，不涉及文件的任务保持空 scope。coordinator workspace 内的绝对路径转换为相对路径，外部路径拒绝。结果返回 `task_id`、`phase` 和审阅事实。委派应能节省时间或上下文，并产出可独立验证的工作。'
  if line.startswith('`team_task_list()`'):
   lines[i]+=(' The first watch omits `after_cursor` for an immediate snapshot; later watches use the cursor returned by watch, not list.' if not suffix else ' 首次 watch 省略 `after_cursor` 获取即时快照，后续使用 watch 返回的 cursor；list 不返回 cursor。')
  if line.startswith('`team_workflow_start(plan)`'):
   lines[i]+=(' Its model-visible schema defines every nested task, bounds, channel, and result field and includes a runnable two-stage example. `channel.viewPolicy` is required. Choose the worker capability from the coordinator prompt; example scopes show an explicit file handoff between dependent tasks.' if not suffix else ' 模型可见 schema 完整定义 task、bounds、channel 和 result 的嵌套字段，并提供可执行的两阶段示例。`channel.viewPolicy` 必填。worker capability 从 coordinator prompt 获取；示例通过明确的文件路径在依赖任务之间交接。')
  if line.startswith('The scoped [`team_task_wait`') or line.startswith('scoped [`team_task_wait`'):
   lines[i]='The scoped [`team_task_wait`](../../../docs/tool-catalog.md#team_task_wait) schema returns terminal phase, complete retained work evidence, and the exact failed outcome. It includes review policy and the selected attempt decision; it excludes worker transcripts and lease internals.' if not suffix else 'scoped [`team_task_wait`](../../../docs/tool-catalog.zh.md#team_task_wait) schema 返回终态、完整保留的工作证据及准确失败原因，并包含审阅策略和选定 attempt 的决定；不包含 worker 对话与 lease 内部状态。'
 p.write_text('\n'.join(lines)+'\n')

paragraphs={
'packages/team/team-scheduler-dag': ('Wake recovery, review dispatch, and new assignments have independent per-drive allowances. `maxReviewDispatchesPerDrive` defaults to `8` and bounds review requests or recovered responses. Exhausting `maxWakeDispatchesPerDrive` ends only wake scanning; eligible new tasks and reviews can still advance. Review-channel creation is idempotent for the exact Team, task, attempt, and reviewer, including an attached channel with no request Envelope yet.', 'Wake 恢复、review 派发与新任务分配分别受每轮额度约束。`maxReviewDispatchesPerDrive` 默认 `8`，限制 review 请求或恢复的响应数。耗尽 `maxWakeDispatchesPerDrive` 只结束 wake 扫描，合格的新任务和 review 仍可推进。Review 频道按准确的 Team、task、attempt 和 reviewer 幂等创建，包括已 attached 但尚无 request Envelope 的频道。'),
'packages/team/team-hub': ('Scheduler review channels use a deterministic identity derived from Team, task, attempt, and reviewer. The Hub revalidates the current scheduler proof and policy before returning an already attached channel. Publication failure or Hub reload can resume that channel without consuming another channel slot; a different attempt receives its own identity.', 'Scheduler review 频道使用从 Team、task、attempt 和 reviewer 派生的确定性身份。Hub 在返回已 attached 频道前重新验证当前 scheduler proof 和策略。请求发布失败或 Hub 重载后可继续使用原频道，不额外消耗频道配额；不同 attempt 使用独立身份。'),
'packages/core/team-link': ('Providers may classify connection failures with `TeamLinkConnectionError.retryable`. A false value requires provider reconfiguration or a new binding rather than repeating the same connection. Registry `team-link/provider-added` notifications let paused consumers retry after a provider is replaced; observer exceptions cannot veto registration. Unknown failures remain eligible for the consumer’s normal reconnect policy.', 'Provider 可通过 `TeamLinkConnectionError.retryable` 分类连接失败。false 表示需要重新配置 provider 或更换 binding，不能重复相同连接。Registry 的 `team-link/provider-added` 通知使暂停的 consumer 在 provider 替换后重试；观察者异常不能否决注册。未知失败仍按 consumer 的正常重连策略处理。'),
'packages/team/team-link-websocket': ('Missing capability, invalid configuration, binding mismatch, malformed frames/results, and unexpected or out-of-order protocol frames are non-retryable connection failures. Transport timeouts and disconnects remain retryable. Remote request rejection alone is not classified as permanent because the remote reason may describe transient admission state.', '缺少 capability、无效配置、binding 不匹配、畸形 frame/result、意外或乱序协议帧属于不可重试的连接失败。传输超时和断线仍可重试。仅凭 remote request rejection 不判定永久失败，因为远端原因可能是暂时的准入状态。'),
}
for root,(en,zh) in paragraphs.items():
 for suffix,text in [('',en),('.zh',zh)]:
  p=Path(root+f'/README{suffix}.md');s=p.read_text();heading=next(l for l in s.splitlines() if l.startswith('## '));insert_before(p,heading,text)

for suffix in ['', '.zh']:
 p=Path(f'packages/team/team-run/README{suffix}.md');s=p.read_text();lines=s.splitlines()
 for i,line in enumerate(lines):
  if line.startswith('For a non-trivial objective') or ('至少两个' in line and 'prompt' in line):
   lines[i]='The coordinator delegates independently deliverable and verifiable work when it saves time or context. Small tightly coupled work can use one executor. Each brief names inputs, output, scope, validation, and handoff; concurrent writers use disjoint scopes. The prompt supplies the configured workflow worker capability and requires retained evidence before synthesis, without duplicating tasks still retrying or cancelling.' if not suffix else 'Coordinator 在能够节省时间或上下文时，委派可独立交付和验证的工作。小型且紧密关联的工作可由一个执行者完成。Brief 明确输入、产物、scope、验收和交接，并行 writer 使用互不重叠的 scope。Prompt 提供已配置的 workflow worker capability，要求整合前检查保留的证据，不重复创建仍在重试或取消中的任务。'
 p.write_text('\n'.join(lines)+'\n')
